// Drive it from outside with status (pending, approved, denied). Pass onDecision to hear the answer.
// Y, A and N answer while the card has focus, so they never fire on a page the person is only reading.
// Pass autoFocus to focus the card once it is in view, so a gate that appears mid-task is answerable at once.
// The countdown only runs while the card is in view, so an unseen request never denies itself.

import { AgentPlan } from "@/components/design-for-ai/agent-plan-steps";

const [state, setState] = useState<"draft" | "running" | "paused" | "complete" | "failed">("draft");

<AgentPlan
  title="Backfill the ledger from billing events"
  steps={planFromAgent}
  state={state}
  onStateChange={setState}
  onApprove={(steps) => api.runs.start(runId, steps)}
/>

// steps: { id, title, duration?, substeps?, outcome?: "done" | "skipped" | "failed", reason? }
// Drive the run from your own backend by setting `state` as each step lands, or let the component tick.

